function parseBlablagues(body, extraImageHost = "") {
  let payload;
  try {
    payload = JSON.parse(body);
  } catch {
    throw Error("Blablagues did not return a JSON image record.");
  }
  const { media, text } = payload?.data?.content ?? {};
  const host =
    typeof media === "string"
      ? /^https:\/\/([a-z0-9.-]+)\/[^#\s\\]+$/i.exec(media)?.[1].toLowerCase()
      : "";
  const allowed =
    host === "blablagues.net" ||
    Boolean(host?.endsWith(".blablagues.net")) ||
    (Boolean(host) &&
      /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/i.test(extraImageHost) &&
      host === extraImageHost.toLowerCase());
  if (!allowed || typeof text !== "string")
    throw Error("Blablagues did not return an approved image URL and its caption.");
  const credit = "https://www.blablagues.net/";
  return { url: media, text: text.trim() ? text.trim() + "\n\n" + credit : credit };
}
const item = $input.first().json;
const extraImageHost = "";
if (item.statusCode !== 200) throw Error("Blablagues did not return a successful image record.");
return [{ json: parseBlablagues(item.body, extraImageHost), pairedItem: { item: 0 } }];

function checkImage(bytes, mime) {
  const type = String(mime ?? "")
    .split(";", 1)[0]
    .trim()
    .toLowerCase();
  if (bytes.length < 12 || bytes.length > 2 * 1024 * 1024)
    throw Error("The image must be within 2 MiB.");
  const png = [137, 80, 78, 71, 13, 10, 26, 10].every((byte, i) => bytes[i] === byte);
  const jpeg = bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  const webp =
    bytes[0] === 82 &&
    bytes[1] === 73 &&
    bytes[2] === 70 &&
    bytes[3] === 70 &&
    bytes[8] === 87 &&
    bytes[9] === 69 &&
    bytes[10] === 66 &&
    bytes[11] === 80;
  const gif =
    bytes[0] === 71 &&
    bytes[1] === 73 &&
    bytes[2] === 70 &&
    bytes[3] === 56 &&
    (bytes[4] === 55 || bytes[4] === 57) &&
    bytes[5] === 97;
  if (type === "image/gif" && gif) return { mimeType: type, fileName: "blablagues.gif" };
  if (type === "image/png" && png) return { mimeType: type, fileName: "blablagues.png" };
  if (type === "image/jpeg" && jpeg) return { mimeType: type, fileName: "blablagues.jpg" };
  if (type === "image/webp" && webp) return { mimeType: type, fileName: "blablagues.webp" };
  throw Error("Blablagues did not return a valid PNG, JPEG, GIF or WebP image.");
}
const item = $input.first();
if (item.json.statusCode !== 200) throw Error("Blablagues did not return a complete image.");
const bytes = await helpers.getBinaryDataBuffer(0, "data");
const metadata = checkImage(bytes, item.binary.data.mimeType);
return [
  {
    json: {},
    binary: {
      data: { ...item.binary.data, fileName: metadata.fileName, mimeType: metadata.mimeType },
    },
    pairedItem: { item: 0 },
  },
];

function confirmUpload(id, raw) {
  const processing = raw?.data?.processing_info;
  if (
    typeof id !== "string" ||
    !/^\d+$/.test(id) ||
    (processing && processing.state !== "succeeded")
  ) {
    throw Error("X did not confirm a ready media upload.");
  }
  return [id];
}
const upload = $input.first().json;
const ids = confirmUpload(upload.data?.id, upload);
return [
  {
    json: { text: $("Check the image URL and caption").item.json.text, media: { media_ids: ids } },
    pairedItem: { item: 0 },
  },
];

function confirmPost(id) {
  if (typeof id !== "string" || !/^\d+$/.test(id))
    throw Error("X did not confirm the post. Check the account before retrying.");
  return id;
}
return [{ json: { id: confirmPost($input.first().json.data?.id) }, pairedItem: { item: 0 } }];
